begin;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000004"}',true);
select public.test_reject($s$insert into public.workspace_members(workspace_id,user_id,role) values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','admin')$s$,'42501');
select public.test_assert((select count(*)=0 from public.workspaces),'invitation possession does not expose wallet rows');
select public.test_assert((select count(*)=0 from public.transactions),'pending financial access denied');
select public.test_assert((select count(*)=0 from public.workspace_invites),'unrelated token enumeration denied');
select public.test_assert((select count(*)=0 from public.user_workspace_ids('20000000-0000-4000-8000-000000000001')),'legacy helper cannot reveal another account memberships');
select public.test_reject($s$select public.qr_join_request_view('ffffffff-ffff-ffff-ffff-ffffffffffff')$s$,'42501');
select public.test_reject($s$insert into public.workspace_join_requests(workspace_id,requester_id,invite_token,status,resolved_at) values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','0123456789abcdef0123456789abcdef','approved',now())$s$,'42501');
select public.test_reject($s$update public.workspace_join_requests set status='approved'$s$,'42501');
select public.test_reject($s$insert into public.workspace_invites(workspace_id) values('10000000-0000-4000-8000-000000000001')$s$,'42501');
select public.test_assert((public.submit_workspace_join_request('0123456789abcdef0123456789abcdef',false)->>'ok')::boolean,'registered requester uses RPC');
select public.test_assert((select count(*)=1 from public.workspace_join_requests),'requester sees own request');
select public.test_assert((select count(*)=0 from public.workspace_members),'pending requester cannot list members');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000005"}',true);
select public.test_assert((select count(*)=0 from public.workspace_join_requests),'other-wallet admin cannot see requests');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000003"}',true);
update public.workspace_members set role='admin' where user_id=auth.uid();
select public.test_assert((select role='member' from public.workspace_members where user_id=auth.uid()),'self-promotion UPDATE cannot change role');
select public.test_assert((select count(*)=1 from public.transactions),'existing member retains financial reads');
select public.test_assert((select count(*)=0 from public.workspace_join_requests),'member cannot see admin queue');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000002"}',true);
select public.test_assert((select count(*)=1 from public.workspace_join_requests),'non-owner admin sees queue');
select public.test_reject($s$insert into public.workspace_members(workspace_id,user_id,role) values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000007','member')$s$,'42501');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000006"}',true);
insert into public.workspaces(id,name,created_by) values('10000000-0000-4000-8000-000000000003','Guest owner test',auth.uid());
insert into public.workspace_members(workspace_id,user_id,role) values('10000000-0000-4000-8000-000000000003',auth.uid(),'admin');
select public.test_assert((select role='admin' from public.workspace_members where user_id=auth.uid()),'guest owner bootstrap preserved');
select public.test_assert((public.manage_workspace_qr('10000000-0000-4000-8000-000000000003','get')->>'code')='registered_account_required','guest bootstrap does not authorize invitation management');
reset role;
set local role anon;
select set_config('request.jwt.claims','{}',true);
select public.test_assert((public.preview_workspace_invite('0123456789abcdef0123456789abcdef')#>>'{value,wallet_name}')='Wallet A','public exact-token minimal preview');
select public.test_assert(not(public.preview_workspace_invite('0123456789abcdef0123456789abcdef')->'value' ? 'workspace_id'),'public preview excludes private ID');
select public.test_assert(not has_function_privilege('anon','public.submit_workspace_join_request(text,boolean)','execute'),'anon cannot execute submission RPC');
select public.test_assert(not has_function_privilege('anon','public.qr_join_request_view(uuid)','execute'),'private DTO helper is not an exposed RPC');
select public.test_assert(not has_function_privilege('anon','public.user_workspace_ids(uuid)','execute'),'anon cannot call the membership helper');
select public.test_assert(not has_table_privilege('anon','public.workspace_members','select'),'anon has no membership table grant');
select public.test_reject($s$select * from public.workspace_members$s$,'42501');
rollback;
